cd <repo>
cat > .tmp/hookdev3/resolve.awk <<'AWK_EOF'
function extract_c_dir(invocation,    m) {
    if (match(invocation, /-C[[:space:]]+("[^"]*"|'"'"'[^'"'"']*'"'"'|[^[:space:]]+)/)) {
        m = substr(invocation, RSTART, RLENGTH)
        sub(/^-C[[:space:]]+/, "", m)
        gsub(/^["'"'"']|["'"'"']$/, "", m)
        return m
    }
    return ""
}

function last_cd_before(prefix,    pos, rest, m, dir, found) {
    pos = 1
    found = ""
    rest = prefix
    while (match(rest, /(^|[&|;(])[[:space:]]*cd[[:space:]]+[^;&|)]+/)) {
        m = substr(rest, RSTART, RLENGTH)
        sub(/^([&|;(])?[[:space:]]*cd[[:space:]]+/, "", m)
        gsub(/^[[:space:]]+|[[:space:]]+$/, "", m)
        dir = m
        sub(/[[:space:]].*/, "", dir)
        if (dir != "") found = dir
        rest = substr(rest, RSTART + RLENGTH)
    }
    return found
}

{
    text = $0
    if (match(text, /(^|[&|;(])[[:space:]]*([A-Za-z_][A-Za-z0-9_]*=[^[:space:]]*[[:space:]]+)*["'"'"']?git["'"'"']?([[:space:]]+-C[[:space:]]+("[^"]*"|'"'"'[^'"'"']*'"'"'|[^[:space:]]+))?[[:space:]]+["'"'"']?push["'"'"']?/)) {
        invocation = substr(text, RSTART, RLENGTH)
        prefix = substr(text, 1, RSTART - 1)
        cdir = extract_c_dir(invocation)
        if (cdir != "") {
            print "C:" cdir
        } else {
            cdir = last_cd_before(prefix)
            if (cdir != "") {
                print "CD:" cdir
            } else {
                print ""
            }
        }
    } else {
        print ""
    }
}
AWK_EOF
echo "written"

