function strip_one_quote(v) {
    if (length(v) >= 2) {
        first = substr(v, 1, 1)
        last = substr(v, length(v), 1)
        if ((first == "\"" && last == "\"") || (first == "'" && last == "'")) {
            return substr(v, 2, length(v) - 2)
        }
    }
    return v
}

{
    text = $0
    scope = ""

    invre = "(^|[&|;(])[[:space:]]*([A-Za-z_][A-Za-z0-9_]*=[^[:space:]]*[[:space:]]+)*[\"']?git[\"']?([[:space:]]+-C[[:space:]]+(\"[^\"]*\"|'[^']*'|[^[:space:]]+))?[[:space:]]+[\"']?push[\"']?[^;&|]*"
    if (match(text, invre)) {
        invocation = substr(text, RSTART, RLENGTH)
        prefix = substr(text, 1, RSTART - 1)

        if (match(invocation, /-C[[:space:]]+("[^"]*"|'[^']*'|[^[:space:]]+)/)) {
            cval = substr(invocation, RSTART, RLENGTH)
            sub(/^-C[[:space:]]+/, "", cval)
            scope = "C:" strip_one_quote(cval)
        } else {
            rest = prefix
            lastdir = ""
            while (match(rest, /(^|[&|;(])[[:space:]]*cd[[:space:]]+[^;&|()]+/)) {
                seg = substr(rest, RSTART, RLENGTH)
                sub(/^[&|;(]?[[:space:]]*cd[[:space:]]+/, "", seg)
                gsub(/^[[:space:]]+|[[:space:]]+$/, "", seg)
                dir = seg
                sub(/[[:space:]].*/, "", dir)
                dir = strip_one_quote(dir)
                if (dir != "") lastdir = dir
                rest = substr(rest, RSTART + RLENGTH)
            }
            if (lastdir != "") scope = "CD:" lastdir
        }
    }

    print scope
}

